SELECT ROUND(
  100.0 * SUM(
    CASE WHEN NOT EXISTS (
      SELECT 1
      FROM member AS m
      WHERE m.link_to_major = major.major_id
    ) THEN 1 ELSE 0 END
  ) / NULLIF(COUNT(*), 0),
  2
) AS percentage_majors_without_members
FROM major;

SELECT ROUND(
  100.0 * SUM(CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) >= 1960 THEN 1 ELSE 0 END) / COUNT(*),
  1
) AS percentage
FROM Patient
WHERE Diagnosis LIKE '%psoriatic arthritis%';

